package com.primehr.evidence.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;import java.util.Objects;
@Entity@Table(name="evidence_artifact")public class EvidenceArtifact extends RspAuditedEntity{
 public enum Kind{LIVE_SOURCE,UPLOAD}public enum SourceType{COMPETENCY_PROFILE,PERFORMANCE_OUTCOME,LD_COMPLETION}public enum Classification{PUBLIC,INTERNAL,CONFIDENTIAL,RESTRICTED}public enum Visibility{OWNER_AND_VALIDATOR,VALIDATOR_ONLY,AGENCY_AUTHORIZED}public enum VerificationStatus{VERIFIED,STALE,BROKEN,UNVERIFIED}
 @Column(name="assessment_case_id",nullable=false,length=36)private String assessmentCaseId;@Column(name="requirement_id",nullable=false,length=36)private String requirementId;@Column(name="requirement_code",nullable=false,length=80)private String requirementCode;@Column(nullable=false,length=250)private String title;@Column(length=3000)private String notes;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Kind kind;
 @Enumerated(EnumType.STRING)@Column(name="source_type",length=30)private SourceType sourceType;@Column(name="source_id",length=100)private String sourceId;@Column(name="source_version")private Long sourceVersion;@Column(name="source_fingerprint",length=64)private String sourceFingerprint;@Column(name="source_label",length=500)private String sourceLabel;@Column(name="source_changed_at")private Instant sourceChangedAt;
 @Column(name="original_filename",length=255)private String originalFilename;@Column(name="storage_provider",length=30)private String storageProvider;@Column(name="storage_object_key",length=500)private String storageObjectKey;@Column(name="media_type",length=120)private String mediaType;@Column(name="byte_size")private Long byteSize;@Column(length=64)private String checksum;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Classification classification;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Visibility visibility;@Column(name="retention_tag",nullable=false,length=100)private String retentionTag;@Column(name="evidence_date",nullable=false)private LocalDate evidenceDate;@Column(name="review_due_date")private LocalDate reviewDueDate;@Column(name="last_verified_at")private Instant lastVerifiedAt;@Enumerated(EnumType.STRING)@Column(name="verification_status",nullable=false,length=20)private VerificationStatus verificationStatus;@Column(name="verification_message",length=1000)private String verificationMessage;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="current_record",nullable=false)private boolean currentRecord;@Column(name="added_by",nullable=false,length=100)private String addedBy;@Column(name="added_at",nullable=false)private Instant addedAt;
 protected EvidenceArtifact(){}
 public static EvidenceArtifact live(String a,String c,String req,String reqCode,String title,String notes,SourceType type,String source,long version,String fingerprint,String label,Instant changed,Classification classification,Visibility visibility,String retention,LocalDate evidenceDate,LocalDate due,String actor,Instant at,String supersedes){var x=new EvidenceArtifact(a,c,req,reqCode,title,notes,Kind.LIVE_SOURCE,classification,visibility,retention,evidenceDate,due,actor,at,supersedes);x.sourceType=Objects.requireNonNull(type);x.sourceId=requiredText(source,"sourceId");if(version<0)throw new IllegalArgumentException("sourceVersion cannot be negative");x.sourceVersion=version;x.sourceFingerprint=requiredText(fingerprint,"sourceFingerprint");x.sourceLabel=requiredText(label,"sourceLabel");x.sourceChangedAt=Objects.requireNonNull(changed);x.verified("Exact live source verified",at);return x;}
 public static EvidenceArtifact upload(String a,String c,String req,String reqCode,String title,String notes,String filename,String provider,String key,String media,long size,String checksum,Classification classification,Visibility visibility,String retention,LocalDate evidenceDate,LocalDate due,String actor,Instant at,String supersedes){var x=new EvidenceArtifact(a,c,req,reqCode,title,notes,Kind.UPLOAD,classification,visibility,retention,evidenceDate,due,actor,at,supersedes);x.originalFilename=requiredText(filename,"filename");x.storageProvider=requiredText(provider,"storageProvider");x.storageObjectKey=requiredText(key,"storageObjectKey");x.mediaType=requiredText(media,"mediaType");if(size<1)throw new IllegalArgumentException("byteSize must be positive");x.byteSize=size;x.checksum=requiredText(checksum,"checksum");x.verified("Uploaded artifact checksum captured",at);return x;}
 private EvidenceArtifact(String a,String c,String req,String reqCode,String title,String notes,Kind kind,Classification classification,Visibility visibility,String retention,LocalDate date,LocalDate due,String actor,Instant at,String supersedes){super(a);assessmentCaseId=requiredText(c,"assessmentCaseId");requirementId=requiredText(req,"requirementId");requirementCode=requiredText(reqCode,"requirementCode");this.title=requiredText(title,"title");this.notes=optionalText(notes);this.kind=kind;this.classification=Objects.requireNonNull(classification);this.visibility=Objects.requireNonNull(visibility);retentionTag=requiredText(retention,"retentionTag");evidenceDate=Objects.requireNonNull(date);if(due!=null&&due.isBefore(date))throw new IllegalArgumentException("reviewDueDate cannot precede evidenceDate");reviewDueDate=due;addedBy=requiredText(actor,"actor");addedAt=Objects.requireNonNull(at);supersedesId=optionalText(supersedes);currentRecord=true;verificationStatus=VerificationStatus.UNVERIFIED;}
 public void supersede(){if(!currentRecord)throw new IllegalStateException("Evidence is already superseded");currentRecord=false;}public void verified(String message,Instant at){verificationStatus=VerificationStatus.VERIFIED;verificationMessage=requiredText(message,"message");lastVerifiedAt=at;}public void failed(VerificationStatus status,String message,Instant at){if(status!=VerificationStatus.STALE&&status!=VerificationStatus.BROKEN)throw new IllegalArgumentException("Failure status must be STALE or BROKEN");verificationStatus=status;verificationMessage=requiredText(message,"message");lastVerifiedAt=at;}
 public String getAssessmentCaseId(){return assessmentCaseId;}public String getRequirementId(){return requirementId;}public String getRequirementCode(){return requirementCode;}public String getTitle(){return title;}public String getNotes(){return notes;}public Kind getKind(){return kind;}public SourceType getSourceType(){return sourceType;}public String getSourceId(){return sourceId;}public Long getSourceVersion(){return sourceVersion;}public String getSourceFingerprint(){return sourceFingerprint;}public String getSourceLabel(){return sourceLabel;}public Instant getSourceChangedAt(){return sourceChangedAt;}public String getOriginalFilename(){return originalFilename;}public String getStorageProvider(){return storageProvider;}public String getStorageObjectKey(){return storageObjectKey;}public String getMediaType(){return mediaType;}public Long getByteSize(){return byteSize;}public String getChecksum(){return checksum;}public Classification getClassification(){return classification;}public Visibility getVisibility(){return visibility;}public String getRetentionTag(){return retentionTag;}public LocalDate getEvidenceDate(){return evidenceDate;}public LocalDate getReviewDueDate(){return reviewDueDate;}public Instant getLastVerifiedAt(){return lastVerifiedAt;}public VerificationStatus getVerificationStatus(){return verificationStatus;}public String getVerificationMessage(){return verificationMessage;}public String getSupersedesId(){return supersedesId;}public boolean isCurrentRecord(){return currentRecord;}public String getAddedBy(){return addedBy;}public Instant getAddedAt(){return addedAt;}
}
